-- PostgreSQL + PostGIS schema for BhuRakshak (the app also creates SQLite tables automatically via SQLAlchemy)
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE users(id SERIAL PRIMARY KEY,name TEXT,mobile TEXT,email TEXT UNIQUE,password_hash TEXT,role TEXT CHECK(role IN('citizen','officer','admin')),created_at TIMESTAMP DEFAULT now());
CREATE TABLE petitions(id SERIAL PRIMARY KEY,petition_code TEXT UNIQUE,user_id INT REFERENCES users(id),mobile TEXT,latitude FLOAT,longitude FLOAT,geom geometry(Point,4326),village_city TEXT,district TEXT,category TEXT,description TEXT,photo_url TEXT,status TEXT DEFAULT 'Submitted',is_anonymous BOOL DEFAULT false,consent_given BOOL,detection_id INT,created_at TIMESTAMP DEFAULT now(),updated_at TIMESTAMP DEFAULT now());
CREATE TABLE scenes(id SERIAL PRIMARY KEY,study_area_name TEXT,image_type TEXT CHECK(image_type IN('before','after')),scene_date DATE,source TEXT,sensor TEXT,cloud_cover_percent FLOAT,spatial_resolution TEXT,image_url TEXT,created_at TIMESTAMP DEFAULT now());
CREATE TABLE detections(id SERIAL PRIMARY KEY,before_scene_id INT REFERENCES scenes(id),after_scene_id INT REFERENCES scenes(id),change_type TEXT,area_hectares FLOAT,confidence FLOAT,risk_score FLOAT,risk_level TEXT,polygon_geojson TEXT,geom geometry(Polygon,4326),ndvi_difference FLOAT,ndwi_difference FLOAT,ndbi_difference FLOAT,bsi_difference FLOAT,status TEXT,evidence TEXT,created_at TIMESTAMP DEFAULT now());
CREATE TABLE gis (id SERIAL PRIMARY KEY,change_detection_id INT REFERENCES detections(id),distance_to_water_m FLOAT,distance_to_road_m FLOAT,distance_to_forest_m FLOAT,near_protected_area BOOL,existing_lulc_class TEXT,explanation TEXT);
CREATE TABLE cases(id SERIAL PRIMARY KEY,petition_id INT REFERENCES petitions(id),change_detection_id INT REFERENCES detections(id),assigned_officer_id INT REFERENCES users(id),status TEXT,officer_decision TEXT,officer_remarks TEXT,permit_reference TEXT,field_photo_url TEXT,decision_date TIMESTAMP,created_at TIMESTAMP DEFAULT now());
CREATE TABLE evidences(id SERIAL PRIMARY KEY,case_id INT NOT NULL REFERENCES cases(id),scene_id INT REFERENCES scenes(id),original_filename TEXT NOT NULL,storage_path TEXT NOT NULL,media_type TEXT NOT NULL,evidence_type TEXT NOT NULL,captured_at TEXT,latitude FLOAT,longitude FLOAT,uploaded_by INT REFERENCES users(id),created_at TIMESTAMP DEFAULT now());
CREATE TABLE portals(id SERIAL PRIMARY KEY,category TEXT,department_name TEXT,portal_name TEXT,portal_url TEXT,required_documents TEXT,last_verified_date TEXT);
CREATE INDEX ON detections USING GIST(geom);CREATE INDEX ON petitions USING GIST(geom);CREATE INDEX ON evidences(case_id);
